-- ============================
-- 6. 评价测试数据 (针对已完成的订单)
-- ============================
INSERT INTO `review` (`order_id`, `user_id`, `homestead_id`, `rating_overall`, `rating_location`, `rating_cleanliness`, `rating_facility`, `rating_service`, `rating_value`, `content`, `tags`, `is_anonymous`, `like_count`, `status`) VALUES
(1, 6, 1, 5, 5, 5, 4, 5, 5, '房子位置很好，就在西湖边上，走路十分钟就到了。房东人很nice，提供了很多游玩建议。房间干净整洁，设施齐全，性价比很高！', '位置优越,干净整洁,房东热情', 0, 12, 1),
(2, 7, 2, 5, 5, 5, 5, 5, 4, '江景房真的很棒，每天早上起来看江景心情都很好。房间很大，装修现代简约，特别喜欢。就是价格稍微有点贵，但是物有所值！', '江景房,装修精美,设施完善', 0, 8, 1),
(3, 8, 3, 4, 4, 5, 4, 4, 5, '古色古香的民宿，很有老杭州的味道。卫生做得很好，住得很舒服。性价比超高，下次还会再来！', '古色古香,性价比高,卫生干净', 0, 15, 1),
(4, 9, 6, 5, 5, 5, 5, 5, 4, '外滩夜景真的太美了！房间豪华大气，各种设施都是高端的。房东服务超级好，随叫随到。唯一的缺点就是太贵了哈哈。', '外滩夜景,豪华装修,服务周到', 0, 23, 1),
(5, 10, 7, 5, 5, 5, 4, 5, 5, '田子坊真的很文艺，周围都是咖啡馆和小店。房间虽然不大但是很温馨，布置很用心。房东是个文艺青年，聊天很投机。', '文艺范,位置优越,房东友好', 0, 11, 1),
(6, 11, 11, 4, 5, 4, 4, 4, 4, '三里屯的位置无敌了，楼下就是各种酒吧和餐厅。房间还不错，就是隔音稍微差了点，晚上有点吵。但整体还是很满意的。', '位置绝佳,交通便利', 0, 9, 1),
(7, 12, 12, 5, 5, 5, 5, 5, 4, '四合院太有特色了！真的是老北京的味道。房东是个地道的北京人，给我们介绍了很多北京的历史文化。住得很舒服，就是价格有点高。', '特色四合院,文化底蕴,房东专业', 0, 18, 1),
(8, 13, 16, 5, 5, 5, 4, 5, 5, '春熙路的位置太方便了，楼下就是商场和美食街。房间干净整洁，设施齐全。性价比超高，强烈推荐！', '位置便利,干净整洁,性价比高', 0, 14, 1),
(9, 14, 17, 5, 5, 5, 5, 5, 5, '宽窄巷子的民宿真的太赞了！川西风格的装修超级有特色，拍照很好看。房东很热情，还请我们喝茶聊天。下次来成都还住这里！', '装修特色,房东热情,体验极佳', 0, 21, 1),
(10, 15, 21, 4, 5, 4, 4, 4, 5, '南山科技园附近，离公司很近，上班很方便。房间设施不错，价格也合理。就是周围吃饭的地方有点少。', '交通便利,价格合理', 0, 7, 1);

